import math
import torch

@torch.no_grad()
def initialize_retention_horizons(gru, history_window, variant):
    # Apply after identical baseline initialization, before optimization.
    # Preserve baseline reset/candidate biases and every recurrent weight.
    if variant == 'baseline':
        return
    if variant not in ('uniform', 'heterogeneous'):
        raise ValueError(variant)
    if not gru.bias:
        raise ValueError('This adaptation requires the supplied GRU to have biases')
    if gru.bidirectional:
        raise ValueError('Preserve the supplied unidirectional GRU4Rec backbone')
    H = gru.hidden_size
    reference = getattr(gru, 'bias_ih_l0')
    horizons = torch.logspace(
        math.log10(2.0), math.log10(float(max(2, history_window))),
        steps=H, device=reference.device, dtype=torch.float64)
    z = 1.0 - horizons.reciprocal()
    if variant == 'uniform':
        z = z.mean().expand_as(z)
    total_bias = (torch.log(z) - torch.log1p(-z)).to(reference.dtype)
    for layer in range(gru.num_layers):
        getattr(gru, f'bias_ih_l{layer}')[H:2*H].copy_(total_bias)
        getattr(gru, f'bias_hh_l{layer}')[H:2*H].zero_()


def final_nonpadding_features(sequence, features):
    # Use original left-padded coordinates, after any packed outputs are restored.
    B, L = sequence.shape
    if L == 0:
        return features.new_zeros((B, features.shape[-1]))
    positions = torch.arange(L, device=sequence.device)
    last = torch.where(sequence.ne(0), positions[None, :], -1).amax(dim=1)
    gathered = features.gather(
        1, last.clamp_min(0)[:, None, None].expand(-1, 1, features.shape[-1])
    ).squeeze(1)
    return torch.where(last[:, None].ge(0), gathered, torch.zeros_like(gathered))

